raw_signs = VOL5_BASE + academic_extras_1 + academic_extras_2
seen = set()
unique_signs = []
for s in raw_signs:
    if s[0] not in seen:
        seen.add(s[0])
        unique_signs.append(s)

final_200 = unique_signs[:200]
assert len(final_200) == 200, f"Expected 200 signs, got {len(final_200)}"

out_path = os.path.join("scripts", "volume_data", "vol5_academic.py")
with open(out_path, "w", encoding="utf-8") as f:
    f.write('"""\nVolume 5: Educational, Academic & Vocational Standards (200 Signs)\n"""\n\n')
    f.write("VOL5_ACADEMIC_200 = [\n")
    for item in final_200:
        f.write(f"    {repr(item)},\n")
    f.write("]\n\n")
    f.write('assert len(VOL5_ACADEMIC_200) == 200, f"Expected 200 signs, got {len(VOL5_ACADEMIC_200)}"\n')

print(f"Successfully generated {out_path} with {len(final_200)} unique signs!")
